import { test } from '@playwright/test'

test('probe overflow', async ({ browser }) => {
  const page = await (await browser.newContext({ viewport: { width: 375, height: 700 } })).newPage()
  await page.goto('/')
  await page.evaluate(() => {
    localStorage.setItem(
      'bill-splitter:v1',
      JSON.stringify({
        people: [{ id: 'a', name: 'Ann' }, { id: 'b', name: 'Bob' }],
        items: [{ id: '1', name: 'X', cents: 5000, people: ['a', 'b'] }],
        payers: [{ personId: 'a', amount: '30' }, { personId: 'b', amount: '20' }],
        tax: '0', tip: '0', currency: 'USD',
      }),
    )
  })
  await page.reload()
  const r = await page.evaluate(() =>
    [...document.querySelectorAll('*')]
      .filter((e) => e.getBoundingClientRect().right > 376)
      .map((e) => `${e.tagName}.${(e.getAttribute('class') ?? '').slice(0, 50)} right=${Math.round(e.getBoundingClientRect().right)}`),
  )
  console.log(r.join('\n'))
})

